/* Zone3 measurement client.
 * Generated by tools/build_analytics.py from data/analytics/config.json.
 * Do not edit this file by hand: edit the register and rebuild.
 *
 * What it does, and what it refuses to do (data/analytics/events.json, rules R1-R5):
 *   - records only what a reader did: a click they made, a page they opened, a CTA they
 *     chose, a disclosure that came into view;
 *   - sets no cookie, creates no identifier, and stores no personal data;
 *   - talks to one owner-controlled endpoint and to nothing else. While that endpoint is
 *     unset, nothing leaves the visitor's browser.
 */
(function () {
  "use strict";

  var CFG = {
  "endpoint": "",
  "storage_key": "z3:events:v1",
  "max_queue": 200,
  "max_age_days": 7,
  "amazon_hosts": [
    "amazon.com",
    "amazon.co.uk",
    "amazon.de",
    "amazon.fr",
    "amazon.ca",
    "amazon.co.jp",
    "amazon.in",
    "amazon.com.au",
    "amazon.com.mx",
    "amazon.com.br",
    "amazon.es",
    "amazon.it",
    "amazon.nl",
    "amazon.se",
    "amazon.pl",
    "amazon.sg",
    "amazon.ae",
    "amazon.sa",
    "amazon.eg",
    "amazon.com.tr",
    "amazon.cn",
    "link.amazon",
    "amzn.to",
    "a.co",
    "amzlinks.in"
  ],
  "guide_prefixes": [
    "/guides/",
    "/site/guides/",
    "/read/",
    "/articles/"
  ],
  "comparison_prefixes": [
    "/read/compare",
    "/site/products",
    "/marketing/comparison",
    "/products"
  ],
  "cta_prefixes": [
    "/guides/",
    "/site/guides/",
    "/read/",
    "/articles/",
    "/shop/",
    "/intent-record/",
    "/marketing/comparison",
    "/site/products",
    "/products"
  ],
  "disclosure_selectors": [
    ".disclose-bar",
    ".z3-strip",
    ".disclose"
  ],
  "local_log_element": "z3-analytics-local"
};

  var QUEUE_KEY = CFG.storage_key;
  var MAX_QUEUE = CFG.max_queue;
  var MAX_AGE_MS = CFG.max_age_days * 86400000;
  var AMAZON_HOSTS = CFG.amazon_hosts;
  var GUIDE_PREFIXES = CFG.guide_prefixes;
  var COMPARISON_PREFIXES = CFG.comparison_prefixes;
  var CTA_PREFIXES = CFG.cta_prefixes;
  var DISCLOSURE_SELECTORS = CFG.disclosure_selectors;

  function now() { return Math.floor(Date.now() / 1000); }

  function utcDate(ts) {
    var d = new Date(ts * 1000);
    return d.toISOString().slice(0, 10);
  }

  function trim(value, max) {
    var s = String(value == null ? "" : value).replace(/\s+/g, " ").trim();
    return s.length > max ? s.slice(0, max - 1) + "\u2026" : s;
  }

  function currentPath() {
    var p = window.location.pathname.replace(/\/+$/, "");
    return p === "" ? "/" : p;
  }

  function readQueue() {
    var raw = null;
    try { raw = window.localStorage.getItem(QUEUE_KEY); } catch (e) { return []; }
    if (!raw) { return []; }
    var parsed;
    try { parsed = JSON.parse(raw); } catch (e) { return []; }
    if (!parsed || !parsed.length) { return []; }
    var cutoff = Date.now() - MAX_AGE_MS;
    var kept = [];
    for (var i = 0; i < parsed.length; i++) {
      var item = parsed[i];
      if (item && item.ts && item.ts * 1000 >= cutoff) { kept.push(item); }
    }
    return kept.slice(-MAX_QUEUE);
  }

  function writeQueue(items) {
    try {
      window.localStorage.setItem(QUEUE_KEY, JSON.stringify(items.slice(-MAX_QUEUE)));
    } catch (e) { /* storage blocked in this browser: the counter stays silent */ }
  }

  function flush(queue) {
    if (!CFG.endpoint || !queue.length) { return; }
    var body = JSON.stringify({ events: queue });
    try {
      if (window.navigator && window.navigator.sendBeacon) {
        var blob = new Blob([body], { type: "application/json" });
        if (window.navigator.sendBeacon(CFG.endpoint, blob)) {
          writeQueue([]);
          return;
        }
      }
    } catch (e) { /* fall through to fetch */ }
    try {
      if (window.fetch) {
        window.fetch(CFG.endpoint, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: body,
          keepalive: true,
          mode: "cors",
          credentials: "omit"
        }).then(function (response) {
          if (response && response.ok) { writeQueue([]); }
        }).catch(function () { /* the queue stays for the next page view */ });
      }
    } catch (e) { /* the queue stays for the next page view */ }
  }

  function record(name, extra) {
    var stamp = now();
    var item = { e: name, p: currentPath(), ts: stamp, d: utcDate(stamp) };
    if (extra) {
      for (var key in extra) {
        if (Object.prototype.hasOwnProperty.call(extra, key)) { item[key] = extra[key]; }
      }
    }
    var queue = readQueue();
    queue.push(item);
    writeQueue(queue);
    flush(queue);
  }

  function hostOf(href) {
    try {
      return new URL(href, window.location.href).hostname.toLowerCase();
    } catch (e) { return ""; }
  }

  function isAmazonHost(host) {
    for (var i = 0; i < AMAZON_HOSTS.length; i++) {
      var candidate = AMAZON_HOSTS[i];
      if (host === candidate || host.slice(-(candidate.length + 1)) === "." + candidate) { return true; }
    }
    return false;
  }

  function matchesAny(path, prefixes) {
    for (var i = 0; i < prefixes.length; i++) {
      if (path.indexOf(prefixes[i]) === 0) { return true; }
    }
    return false;
  }

  function targetFor(href) {
    var url;
    try { url = new URL(href, window.location.href); } catch (e) { return trim(href, 120); }
    var asin = url.pathname.match(/\/(?:dp|gp\/product)\/([A-Za-z0-9]{10})/);
    if (asin) { return asin[1].toUpperCase(); }
    return trim(url.hostname + url.pathname, 120);
  }

  function onClick(event) {
    var node = event.target;
    if (!node || !node.closest) { return; }
    var link = node.closest("a[href]");
    if (!link) { return; }
    var href = link.getAttribute("href") || "";
    if (!href || href.charAt(0) === "#" || href.indexOf("mailto:") === 0) { return; }
    var host = hostOf(href);
    var label = trim(link.textContent || link.getAttribute("aria-label") || "", 60);
    if (isAmazonHost(host)) {
      record("outbound_click", { t: targetFor(href), l: label });
      return;
    }
    var path = href.split("#")[0].split("?")[0];
    if (path.charAt(0) === "/" && matchesAny(path, CTA_PREFIXES)) {
      record("cta_click", { t: trim(path, 120), l: label });
    }
  }

  function disclosureElement() {
    for (var i = 0; i < DISCLOSURE_SELECTORS.length; i++) {
      var el = document.querySelector(DISCLOSURE_SELECTORS[i]);
      if (el) { return el; }
    }
    return null;
  }

  function inViewport(el) {
    try {
      var box = el.getBoundingClientRect();
      var height = window.innerHeight || 0;
      return box.top < height && box.bottom > 0;
    } catch (e) { return false; }
  }

  function onDisclosure() {
    var el = disclosureElement();
    if (!el) { return; }
    if (!window.IntersectionObserver) {
      record("disclosure_impression", { a: inViewport(el) });
      return;
    }
    var observer = new window.IntersectionObserver(function (entries) {
      for (var i = 0; i < entries.length; i++) {
        if (entries[i].isIntersecting) {
          record("disclosure_impression", { a: inViewport(el) });
          observer.disconnect();
        }
      }
    }, { threshold: 0.5 });
    observer.observe(el);
  }

  function renderLocalLog() {
    var host = document.getElementById(CFG.local_log_element);
    if (!host) { return; }
    var queue = readQueue();
    var heading = document.createElement("h3");
    heading.textContent = "Events recorded in this browser";
    var note = document.createElement("p");
    note.className = "z3-meta";
    note.textContent = queue.length
      ? "The counter below is running on this device. Nothing has been sent anywhere: the collection endpoint is not configured, so these events stay in this browser only."
      : "No events are stored in this browser yet. Open a guide, then follow a link to Amazon, and come back to this page.";
    host.appendChild(heading);
    host.appendChild(note);
    var list = document.createElement("ul");
    list.className = "z3-prose";
    for (var i = Math.max(0, queue.length - 12); i < queue.length; i++) {
      var item = queue[i];
      var entry = document.createElement("li");
      entry.textContent = item.d + " " + item.e + " " + item.p + (item.t ? " -> " + item.t : "");
      list.appendChild(entry);
    }
    host.appendChild(list);
  }

  function start() {
    var path = currentPath();
    if (matchesAny(path, GUIDE_PREFIXES)) { record("guide_view", {}); }
    if (matchesAny(path, COMPARISON_PREFIXES)) { record("comparison_view", {}); }
    document.addEventListener("click", onClick, true);
    onDisclosure();
    renderLocalLog();
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", start);
  } else {
    start();
  }
})();
